import os
import requests

def poll_transcription(payload, config=None):
    config = config or {}
    import time
    api_key = os.getenv("ASSEMBLYAI_API_KEY") or config.get("api_key")
    headers = {"authorization": api_key}
    audio_url = payload.get("audio_url")
    job = requests.post("https://api.assemblyai.com/v2/transcript", json={"audio_url": audio_url}, headers=headers).json()
    job_id = job["id"]
    while True:
        res = requests.get(f"https://api.assemblyai.com/v2/transcript/{job_id}", headers=headers).json()
        if res["status"] == "completed":
            transcript = res["text"]
            break
        elif res["status"] == "error":
            raise RuntimeError(res.get("error", "Unknown error"))
        time.sleep(3)
    result = transcript
    return result
